select reported_cost as BilledCost, toString(toUUID('00000000-0000-4000-8000-000000000001')) as BillingAccountId, CAST(NULL AS Nullable(String)) as BillingAccountName, 'USD' as BillingCurrency, toTimeZone(toDateTime(addMonths(toStartOfMonth(charge_period_start), 1), 'UTC'), 'UTC') as BillingPeriodEnd, toTimeZone(toDateTime(toStartOfMonth(charge_period_start), 'UTC'), 'UTC') as BillingPeriodStart, 'Usage' as ChargeCategory, CAST(NULL AS Nullable(String)) as ChargeClass, CAST(NULL AS Nullable(String)) as ChargeDescription, 'Usage-Based' as ChargeFrequency, toTimeZone(charge_period_end, 'UTC') as ChargePeriodEnd, toTimeZone(charge_period_start, 'UTC') as ChargePeriodStart, reported_cost as ContractedCost, reported_cost as EffectiveCost, nullIf(CAST(provider AS String), '') as HostProviderName, nullIf(CAST(provider AS String), '') as InvoiceIssuerName, reported_cost as ListCost, CAST(NULL AS Nullable(Decimal(38, 9))) as PricingQuantity, CAST(NULL AS Nullable(String)) as PricingUnit, nullIf(CAST(provider AS String), '') as ProviderName, nullIf(CAST(provider AS String), '') as PublisherName, nullIf(CAST(region AS String), '') as RegionId, nullIf(CAST(region AS String), '') as RegionName, 'AI and Machine Learning' as ServiceCategory, nullIf(CAST(model AS String), '') as ServiceName, nullIf(CAST(provider AS String), '') as ServiceProviderName, 'Generative AI' as ServiceSubcategory, nullIf(named_tags, '{}') as Tags, reported_cost as x_ReportedCost, reported_cache_cost as x_ReportedCacheCost, quantity_input_tokens as x_InputTokens, quantity_input_text_tokens as x_InputTextTokens, quantity_input_audio_tokens as x_InputAudioTokens, quantity_input_image_tokens as x_InputImageTokens, quantity_input_cache_read_tokens as x_InputCacheReadTokens, quantity_input_cache_read_text_tokens as x_InputCacheReadTextTokens, quantity_input_cache_read_audio_tokens as x_InputCacheReadAudioTokens, quantity_input_cache_read_image_tokens as x_InputCacheReadImageTokens, quantity_input_cache_read_video_tokens as x_InputCacheReadVideoTokens, quantity_input_cache_write_tokens as x_InputCacheWriteTokens, quantity_input_cache_write_text_tokens as x_InputCacheWriteTextTokens, quantity_input_cache_write_audio_tokens as x_InputCacheWriteAudioTokens, quantity_input_cache_write_image_tokens as x_InputCacheWriteImageTokens, quantity_input_cache_write_video_tokens as x_InputCacheWriteVideoTokens, quantity_output_tokens as x_OutputTokens, quantity_output_text_tokens as x_OutputTextTokens, quantity_output_audio_tokens as x_OutputAudioTokens, quantity_output_reasoning_tokens as x_OutputReasoningTokens, quantity_accepted_prediction_tokens as x_AcceptedPredictionTokens, quantity_rejected_prediction_tokens as x_RejectedPredictionTokens, quantity_realtime_audio_ms as x_RealtimeAudioMilliseconds, quantity_reported_total_tokens as x_ReportedTotalTokens, nullIf(substringIndex(subject, '/', 1), '') as x_SubjectType, nullIf(substring(subject, position(subject, '/') + 1), '') as x_SubjectId, nullIf(toString(application_id), '00000000-0000-0000-0000-000000000000') as x_ApplicationId, arrayMap(team -> substringIndex(team, '/', 1), teams) as x_TeamTypes, arrayMap(team -> substring(team, position(team, '/') + 1), teams) as x_TeamIds
from (
  select
    toStartOfDay(time, 'UTC') as charge_period_start,
    charge_period_start + INTERVAL 1 DAY as charge_period_end,
    provider, model, region, subject, application_id, teams,
    toJSONString(CAST(
      mapFilter((tag_key, tag_value) -> has(['env', 'cost_center'], tag_key), tags)
      AS Map(String, String)
    )) as named_tags,
    CAST(sum(reported_cost_usd) AS Decimal(38, 9)) as reported_cost,
    CAST(sum(reported_cache_cost_usd) AS Decimal(38, 9)) as reported_cache_cost,
    sum(toDecimal128(input_tokens, 0)) as quantity_input_tokens, sum(toDecimal128(input_text_tokens, 0)) as quantity_input_text_tokens, sum(toDecimal128(input_audio_tokens, 0)) as quantity_input_audio_tokens, sum(toDecimal128(input_image_tokens, 0)) as quantity_input_image_tokens, sum(toDecimal128(input_cache_read_tokens, 0)) as quantity_input_cache_read_tokens, sum(toDecimal128(input_cache_read_text_tokens, 0)) as quantity_input_cache_read_text_tokens, sum(toDecimal128(input_cache_read_audio_tokens, 0)) as quantity_input_cache_read_audio_tokens, sum(toDecimal128(input_cache_read_image_tokens, 0)) as quantity_input_cache_read_image_tokens, sum(toDecimal128(input_cache_read_video_tokens, 0)) as quantity_input_cache_read_video_tokens, sum(toDecimal128(input_cache_write_tokens, 0)) as quantity_input_cache_write_tokens, sum(toDecimal128(input_cache_write_text_tokens, 0)) as quantity_input_cache_write_text_tokens, sum(toDecimal128(input_cache_write_audio_tokens, 0)) as quantity_input_cache_write_audio_tokens, sum(toDecimal128(input_cache_write_image_tokens, 0)) as quantity_input_cache_write_image_tokens, sum(toDecimal128(input_cache_write_video_tokens, 0)) as quantity_input_cache_write_video_tokens, sum(toDecimal128(output_tokens, 0)) as quantity_output_tokens, sum(toDecimal128(output_text_tokens, 0)) as quantity_output_text_tokens, sum(toDecimal128(output_audio_tokens, 0)) as quantity_output_audio_tokens, sum(toDecimal128(output_reasoning_tokens, 0)) as quantity_output_reasoning_tokens, sum(toDecimal128(accepted_prediction_tokens, 0)) as quantity_accepted_prediction_tokens, sum(toDecimal128(rejected_prediction_tokens, 0)) as quantity_rejected_prediction_tokens, sum(toDecimal128(realtime_audio_ms, 0)) as quantity_realtime_audio_ms, sum(toDecimal128(reported_total_tokens, 0)) as quantity_reported_total_tokens
  from usage_events final
  where tenant_id = toUUID('00000000-0000-4000-8000-000000000001') and time >= toDateTime64('2026-09-01 00:00:00.000', 3, 'UTC') and time < toDateTime64('2026-10-01 00:00:00.000', 3, 'UTC')
  group by charge_period_start, charge_period_end, provider, model, region, subject,
    application_id, teams, named_tags
)
order by charge_period_start, provider, model, region, subject, toString(application_id),
  teams, Tags nulls first
